var documenterSearchIndex = {"docs":
[{"category":"section","location":"multi_phase_models/#Multiphase-Models","page":"Multiphase Models","text":"BusInjectionModel.jl provides methods to build many different variations of the Branch Flow Model, including single phase and multiphase models. Each of the multihpase model types supported are documented below.\n\nPages = [\"multi_phase_models.md\"]\nDepth = 2","title":"Multiphase Models"},{"category":"section","location":"multi_phase_models/#Unrelaxed-models","page":"Multiphase Models","text":"The Unrelaxed multiphase model is built by passing a JuMP.Model, Network{MultiPhase}, and the Unrelaxed type to build_bim_rectangular!.\n\nnet = CommonOPF.Network_IEEE13()\nm = JuMP.Model()\n\nbuild_bim_rectangular!(m, net, Unrelaxed)\nprintln(\"Variable information:\")\nCommonOPF.print_var_info(net)\nprintln(\"Constraint information:\")\nCommonOPF.print_constraint_info(net)\nVariable information:\n┌────────┬───────────────────────────────────────────────────────────┬──────────────────┬────────────────────┐\n│ symbol │                                               description │            units │         dimensions │\n├────────┼───────────────────────────────────────────────────────────┼──────────────────┼────────────────────┤\n│     s0 │ complex net bus power injection at the net.substation_bus │ ComplexPowerUnit │ (Bus, Time, Phase) │\n├────────┼───────────────────────────────────────────────────────────┼──────────────────┼────────────────────┤\n│      v │                                    complex voltage vector │         VoltUnit │ (Bus, Time, Phase) │\n└────────┴───────────────────────────────────────────────────────────┴──────────────────┴────────────────────┘\nConstraint information:\n┌─────────────────────────────────┬────────────────────────────────────────────┬──────────────────────────────────────┬────────────────────┐\n│                          symbol │                                description │                             set_type │         dimensions │\n├─────────────────────────────────┼────────────────────────────────────────────┼──────────────────────────────────────┼────────────────────┤\n│ bus_power_injection_constraints │ net power injection definition at each bus │ MathOptInterface.EqualTo{ComplexF64} │ (Bus, Time, Phase) │\n└─────────────────────────────────┴────────────────────────────────────────────┴──────────────────────────────────────┴────────────────────┘\n\nThe math underlying the model is as follows:\n\nboldsymbol s_j^Phi_j = sum_k j sim k textdiag left(  \n    boldsymbol v_j^Phi_jk left boldsymbol v_j^Phi_jk - boldsymbol v_k^Phi_jk  right^H boldsymbol Y_jk^H\nright)\nquad forall j in mathcalN\n\nFor the nomenclature see TODO.","title":"Unrelaxed models"},{"category":"section","location":"multi_phase_models/#FixedPointLinear-models","page":"Multiphase Models","text":"The FixedPointLinear multiphase model is built by passing a JuMP.Model, Network{MultiPhase}, and the FixedPointLinear type to build_bim_rectangular!.\n\nnet = CommonOPF.Network_IEEE13()\nm = JuMP.Model()\n\nbuild_bim_rectangular!(m, net, FixedPointLinear)\nprintln(\"Variable information:\")\nCommonOPF.print_var_info(net)\nprintln(\"Constraint information:\")\nCommonOPF.print_constraint_info(net)\nVariable information:\n┌────────┬──────────────────────────────────────┬──────────────────┬─────────────────────┐\n│ symbol │                          description │            units │          dimensions │\n├────────┼──────────────────────────────────────┼──────────────────┼─────────────────────┤\n│      s │ complex terminal net power injection │ ComplexPowerUnit │ (BusTerminal, Time) │\n├────────┼──────────────────────────────────────┼──────────────────┼─────────────────────┤\n│      v │             complex terminal voltage │         VoltUnit │ (BusTerminal, Time) │\n└────────┴──────────────────────────────────────┴──────────────────┴─────────────────────┘\nConstraint information:\n┌──────────────────┬────────────────────────────────────────────────────┬───────────────────────────────────────┬─────────────────────┐\n│           symbol │                                        description │                              set_type │          dimensions │\n├──────────────────┼────────────────────────────────────────────────────┼───────────────────────────────────────┼─────────────────────┤\n│  fixed_point_con │                       fixed point voltage equation │  MathOptInterface.EqualTo{ComplexF64} │ (Time, BusTerminal) │\n├──────────────────┼────────────────────────────────────────────────────┼───────────────────────────────────────┼─────────────────────┤\n│ s_lower_imag_con │ lower bound on imaginary power injection variables │ MathOptInterface.GreaterThan{Float64} │ (BusTerminal, Time) │\n├──────────────────┼────────────────────────────────────────────────────┼───────────────────────────────────────┼─────────────────────┤\n│ s_lower_real_con │      lower bound on real power injection variables │ MathOptInterface.GreaterThan{Float64} │ (BusTerminal, Time) │\n├──────────────────┼────────────────────────────────────────────────────┼───────────────────────────────────────┼─────────────────────┤\n│ s_upper_imag_con │ upper bound on imaginary power injection variables │    MathOptInterface.LessThan{Float64} │ (BusTerminal, Time) │\n├──────────────────┼────────────────────────────────────────────────────┼───────────────────────────────────────┼─────────────────────┤\n│ s_upper_real_con │      upper bound on real power injection variables │    MathOptInterface.LessThan{Float64} │ (BusTerminal, Time) │\n└──────────────────┴────────────────────────────────────────────────────┴───────────────────────────────────────┴─────────────────────┘\n\nThe math underlying the model is as follows:\n\nboldsymbol v = -boldsymbol Y_LL^-1 Y_L0 boldsymbol v_0 + Y_LL^-1 textdiag(boldsymbol v_FP^*)^-1 boldsymbol s^*\n\nFor the nomenclature see TODO.","title":"FixedPointLinear models"},{"category":"section","location":"methods/#Methods","page":"Methods","text":"Pages = [\"single_phase_models.md\"]\nDepth = 2","title":"Methods"},{"category":"section","location":"methods/#Model-builders","page":"Methods","text":"","title":"Model builders"},{"category":"function","location":"methods/#BusInjectionModel.build_bim_rectangular!","page":"Methods","text":"build_bim_rectangular!(m::JuMP.AbstractModel, net::Network, mtype::ModelType=Unrelaxed)\n\nTop-level model builder that dispatches the ModelType enum\n\n\n\n\n\nbuild_bim_rectangular!(m::JuMP.AbstractModel, net::Network{SinglePhase}, ::Val{Unrelaxed})\n\nModel builder for single-phase, unrelaxed BIM with rectangular voltage variables. See the      Single Phase Bus Injection Model (Unrelaxed) math for details.\n\nAdds the variables:\n\nm[:v] with complex values for all busses in CommonOPF.busses(net)\nm[:s0] for the complex slack bus power injection\n\n\n\n\n\nbuild_bim_rectangular!(m::JuMP.AbstractModel, net::Network{MultiPhase}, ::Val{Unrelaxed})\n\nModel builder for multi-phase, unrelaxed BIM with rectangular voltage variables. See the      Multi-Phase Bus Injection Model (Unrelaxed) math for details.\n\nAdds the variables:\n\nm[:v] with complex values for all busses in CommonOPF.busses(net)\nm[:s0] for the complex slack bus power injection\n\n\n\n\n\nbuild_bim_rectangular!(m::JuMP.Model, net::Network, ::Val{FixedPointLinear})\n\nBuild the fixed point linear model.\n\n\n\n\n\n","title":"BusInjectionModel.build_bim_rectangular!"},{"category":"function","location":"methods/#BusInjectionModel.build_bim_polar!","page":"Methods","text":"build_bim_polar!(m::JuMP.AbstractModel, net::Network{SinglePhase}, ::Val{DC})\n\nBuild the classic DC OPF model. \n\nVariables:\n\npj net bus power injection variable\np_gen all generators are given real power injection decision variables at their busses.\nv_ang voltage angle at all busses\n\n\n\n\n\nbuild_bim_polar!(m::JuMP.AbstractModel, net::Network, mtype::ModelType=Unrelaxed)\n\nTop-level model builder that dispatches the ModelType enum\n\n\n\n\n\nbuild_bim_polar!(m::JuMP.AbstractModel, net::Network{SinglePhase}, ::Val{Unrelaxed})\n\nModel builder for single-phase, unrelaxed BIM with polar voltage variables. See the      Single Phase Bus Injection Model (Unrelaxed) math for details.\n\nAdds the variables:\n\nm[:v_mag] for all busses in CommonOPF.busses(net)\nm[:v_ang] for all busses in CommonOPF.busses(net)\nm[:pj] and m[:qj] for the bus power injections\nm[:q_gen] for any P-V busses (via the CommonOPF.Generator)\n\n\n\n\n\n","title":"BusInjectionModel.build_bim_polar!"},{"category":"function","location":"methods/#BusInjectionModel.add_or_update_fixed_point_constraint","page":"Methods","text":"add_or_update_fixed_point_constraint(\n    m::JuMP.Model, \n    net::Network, \n    v_fp::Matrix{ComplexF64},\n)\n\nApply the fixed point voltage constraint to the model m. If :fixed_point_con in keys(m.obj_dict) then the existing constraints are deleted first.\n\n\n\n\n\n","title":"BusInjectionModel.add_or_update_fixed_point_constraint"},{"category":"function","location":"methods/#BusInjectionModel.add_complex_terminal_power_variable","page":"Methods","text":"add_complex_terminal_power_variable(\n    m::JuMP.Model, \n    net::Network, \n    trmnls::Vector{CommonOPF.BusTerminal},\n)\n\nAdd an :s variable to the model. If the net.bounds for s are missing the default bounds are zero (to keep the model bounded).\n\n\n\n\n\n","title":"BusInjectionModel.add_complex_terminal_power_variable"},{"category":"function","location":"methods/#BusInjectionModel.add_complex_terminal_voltage_variable","page":"Methods","text":"add_complex_terminal_voltage_variable(\n    m::JuMP.Model, \n    net::Network, \n    trmnls::Vector{CommonOPF.BusTerminal},\n)\n\nAdd a variable with symbol :v for the complex voltage indexed on trmnls and 1:net.Ntimesteps\n\n\n\n\n\n","title":"BusInjectionModel.add_complex_terminal_voltage_variable"},{"category":"section","location":"math/#Single-Phase-Bus-Injection-Model-(Unrelaxed)","page":"Math","text":"","title":"Single Phase Bus Injection Model (Unrelaxed)"},{"category":"section","location":"math/#Rectangular-voltage-variables","page":"Math","text":"Notation:\n\ns_j net complex power injection at node j\nmathcalN set of all nodes in network\nv_j voltage at node j\n\nbeginaligned\ns_j = sum_k j sim k Yjk^* ( v_j^2 - v_j v_k^*)  forall j in mathcalN \nv_textsubstation bus = v_0\nendaligned","title":"Rectangular voltage variables"},{"category":"section","location":"math/#Polar-voltage-variables","page":"Math","text":"Notation:\n\nG_ij real entry of admittance matrix at row i, column j\nB_ij imaginary entry of admittance matrix at row i, column j\nv_j voltage magnitude at bus j\nangle v_j voltage angle at bus j\np_j real power injection at bus j\nq_j reactive power injection at bus j\n\nbeginaligned\np_j =  v_j sum_i in 1dotsmathcalN v_i left\n     G_ij cos(angle v_j - angle v_i) + B_ij sin(angle v_j - angle v_i)\n     right  \nq_j =  v_j sum_i in 1dotsmathcalN v_i left\n     G_ij sin(angle v_j - angle v_i) - B_ij cos(angle v_j - angle v_i)\n     right  \nv_textsubstation bus = v_0 \nangle v_textsubstation bus = 0\nendaligned","title":"Polar voltage variables"},{"category":"section","location":"math/#Multi-Phase-Bus-Injection-Model-(Unrelaxed)","page":"Math","text":"","title":"Multi-Phase Bus Injection Model (Unrelaxed)"},{"category":"section","location":"math/#Rectangular-voltage-variables-2","page":"Math","text":"Notation:\n\nboldsymbol s_j net complex power injection at bus j, vector of phases\nPhi_j phases connected to bus j (take sub-set of vector)\nboldsymbol v_j^Phi_jk complex voltage vector at bus j for the phases connected to bus k\nk j sim k set of busses connected to bus j\nH conjugate transpose\nboldsymbol Y_jk^H phase admittance matrix for busses j and k\n\nbeginaligned\nboldsymbol s_j^Phi_j = sum_k j sim k textdiag left(  \n     boldsymbol v_j^Phi_jk left boldsymbol v_j^Phi_jk - boldsymbol v_k^Phi_jk  right^H boldsymbol Y_jk^H\nright)\nquad forall j in mathcalN\nendaligned","title":"Rectangular voltage variables"},{"category":"section","location":"#BusInjectionModel.jl","page":"User Documentation","text":"Documentation for BusInjectionModel.jl\n\nA work-in-progress package for optimal power flow (OPF) models based on the bus injection model.\n\nThis package is part of a federation of packages to support OPF modeling:\n\nCommonOPF provides the basis for BusInjectionModel.jl and:\nBranchFlowModel, which provides a similar interface to BusInjectionModel.jl.","title":"BusInjectionModel.jl"},{"category":"section","location":"#Inputs","page":"User Documentation","text":"Inputs are defined using CommonOPF.Network structs. ","title":"Inputs"},{"category":"section","location":"#Building-a-Model","page":"User Documentation","text":"Building a BranchFlBusInjectionModelowModel requires three things:\n\na JuMP Model,\na CommonOPF.Network, and\nthe type of model to be built, i.e. one of the BusInjectionModel.ModelType\n\nTo build a model see build_bim_rectangular! and build_bim_polar!","title":"Building a Model"},{"category":"type","location":"#BusInjectionModel.ModelType","page":"User Documentation","text":"ModelType\n\nAn enum with values:\n\nFixedPointLinear\nUnrelaxed\nDC (single phase polar only)\n\n\n\n\n\n","title":"BusInjectionModel.ModelType"},{"category":"section","location":"single_phase_models/#Single-Phase-Models","page":"Single Phase Models","text":"BusInjectionModel.jl provides methods to build many different variations of the Branch Flow Model, including single phase and multiphase models. Each of the single phase model types supported are documented below.\n\nPages = [\"single_phase_models.md\"]\nDepth = 3","title":"Single Phase Models"},{"category":"section","location":"single_phase_models/#Unrelaxed-models","page":"Single Phase Models","text":"The Unrelaxed multiphase model is built by passing a JuMP.Model, Network{SinglePhase}, and the Unrelaxed type to build_bim_rectangular! or build_bim_polar!.","title":"Unrelaxed models"},{"category":"section","location":"single_phase_models/#Rectangular-Voltage","page":"Single Phase Models","text":"net = CommonOPF.Network_IEEE13_SinglePhase()\nm = JuMP.Model()\n\nbuild_bim_rectangular!(m, net, Unrelaxed)\nprintln(\"Variable information:\")\nCommonOPF.print_var_info(net)\nprintln(\"Constraint information:\")\nCommonOPF.print_constraint_info(net)\nVariable information:\n┌────────┬───────────────────────────────────────────────────────────┬──────────────────┬─────────────┐\n│ symbol │                                               description │            units │  dimensions │\n├────────┼───────────────────────────────────────────────────────────┼──────────────────┼─────────────┤\n│     s0 │ complex net bus power injection at the net.substation_bus │ ComplexPowerUnit │ (Bus, Time) │\n├────────┼───────────────────────────────────────────────────────────┼──────────────────┼─────────────┤\n│      v │                                    complex voltage vector │         VoltUnit │ (Bus, Time) │\n└────────┴───────────────────────────────────────────────────────────┴──────────────────┴─────────────┘\nConstraint information:\n┌─────────────────────────────────┬────────────────────────────────────────────┬──────────────────────────────────────┬─────────────┐\n│                          symbol │                                description │                             set_type │  dimensions │\n├─────────────────────────────────┼────────────────────────────────────────────┼──────────────────────────────────────┼─────────────┤\n│ bus_power_injection_constraints │ net power injection definition at each bus │ MathOptInterface.EqualTo{ComplexF64} │ (Bus, Time) │\n└─────────────────────────────────┴────────────────────────────────────────────┴──────────────────────────────────────┴─────────────┘\n\nThe math underlying the model is as follows:\n\ns_j = sum_k j sim k Y_jk^* left( v_j^2 - v_j v_k^* right)\nquad forall j in mathcalN\n\nFor the nomenclature see TODO.","title":"Rectangular Voltage"},{"category":"section","location":"single_phase_models/#Polar-Voltage","page":"Single Phase Models","text":"net = CommonOPF.Network_IEEE13_SinglePhase()\nm = JuMP.Model()\n\nbuild_bim_polar!(m, net, Unrelaxed)\nprintln(\"Variable information:\")\nCommonOPF.print_var_info(net)\nprintln(\"Constraint information:\")\nCommonOPF.print_constraint_info(net)\nVariable information:\n┌────────┬──────────────────────────────────┬───────────────────┬─────────────┐\n│ symbol │                      description │             units │  dimensions │\n├────────┼──────────────────────────────────┼───────────────────┼─────────────┤\n│     pj │    real net bus power injection  │     RealPowerUnit │ (Bus, Time) │\n├────────┼──────────────────────────────────┼───────────────────┼─────────────┤\n│     qj │ reactive net bus power injection │ ReactivePowerUnit │ (Bus, Time) │\n├────────┼──────────────────────────────────┼───────────────────┼─────────────┤\n│  v_ang │                    voltage angle │       RadiansUnit │ (Bus, Time) │\n├────────┼──────────────────────────────────┼───────────────────┼─────────────┤\n│  v_mag │                voltage magnitude │          VoltUnit │ (Bus, Time) │\n└────────┴──────────────────────────────────┴───────────────────┴─────────────┘\nConstraint information:\n┌──────────────────────────────────────────┬─────────────────────────────────────────────────────┬───────────────────────────────────┬─────────────┐\n│                                   symbol │                                         description │                          set_type │  dimensions │\n├──────────────────────────────────────────┼─────────────────────────────────────────────────────┼───────────────────────────────────┼─────────────┤\n│ bus_reactive_power_injection_constraints │ net reactive power injection definition at each bus │ MathOptInterface.EqualTo{Float64} │ (Bus, Time) │\n├──────────────────────────────────────────┼─────────────────────────────────────────────────────┼───────────────────────────────────┼─────────────┤\n│     bus_real_power_injection_constraints │     net real power injection definition at each bus │ MathOptInterface.EqualTo{Float64} │ (Bus, Time) │\n└──────────────────────────────────────────┴─────────────────────────────────────────────────────┴───────────────────────────────────┴─────────────┘\n\nThe math underlying the model is as follows:\n\nbeginaligned\np_j =  v_j sum_i in 1dotsmathcalN v_i left\n    G_leftijright cos(angle v_j - angle v_i) + B_leftijright sin(angle v_j - angle v_i)\n    right\n    quad forall j in mathcalN\n\nq_j =  v_j sum_i in 1dotsmathcalN v_i left\n    G_leftijright sin(angle v_j - angle v_i) - B_leftijright cos(angle v_j - angle v_i)\n    right\n    quad forall j in mathcalN\n\nv_textsubstation bus = v_0 \n\nangle v_textsubstation bus = 0\nendaligned","title":"Polar Voltage"},{"category":"section","location":"single_phase_models/#DC-Model","page":"Single Phase Models","text":"net = CommonOPF.Network_IEEE5()\nm = JuMP.Model()\n\nbuild_bim_polar!(m, net, DC)\nprintln(\"Variable information:\")\nCommonOPF.print_var_info(net)\nprintln(\"Constraint information:\")\nCommonOPF.print_constraint_info(net)\nVariable information:\n┌────────┬────────────────────────────────┬───────────────┬─────────────┐\n│ symbol │                    description │         units │  dimensions │\n├────────┼────────────────────────────────┼───────────────┼─────────────┤\n│  p_gen │ generator bus power injection  │ RealPowerUnit │ (Bus, Time) │\n├────────┼────────────────────────────────┼───────────────┼─────────────┤\n│     pj │  real net bus power injection  │ RealPowerUnit │ (Bus, Time) │\n├────────┼────────────────────────────────┼───────────────┼─────────────┤\n│  v_ang │                  voltage angle │   RadiansUnit │ (Bus, Time) │\n└────────┴────────────────────────────────┴───────────────┴─────────────┘\nConstraint information:\n┌──────────────────────────────────────┬──────────────────────────────────────────────────────────────────────────────────────────────────┬───────────────────────────────────┬─────────────┐\n│                               symbol │                                                                                      description │                          set_type │  dimensions │\n├──────────────────────────────────────┼──────────────────────────────────────────────────────────────────────────────────────────────────┼───────────────────────────────────┼─────────────┤\n│ bus_real_power_injection_constraints │ net real power injection at each bus equals the negative susceptance matrix times voltage angles │ MathOptInterface.EqualTo{Float64} │ (Time, Bus) │\n├──────────────────────────────────────┼──────────────────────────────────────────────────────────────────────────────────────────────────┼───────────────────────────────────┼─────────────┤\n│                         load_balance │                                        total net real power injection in the network equals zero │ MathOptInterface.EqualTo{Float64} │    (Time, ) │\n├──────────────────────────────────────┼──────────────────────────────────────────────────────────────────────────────────────────────────┼───────────────────────────────────┼─────────────┤\n│                      reference_angle │                                                voltage angle at the substation bus fixed to zero │ MathOptInterface.EqualTo{Float64} │    (Time, ) │\n└──────────────────────────────────────┴──────────────────────────────────────────────────────────────────────────────────────────────────┴───────────────────────────────────┴─────────────┘\n\nThe math underlying the model is as follows:\n\nboldsymbol p_j = -boldsymbol B boldsymbol theta_j \n\nwhere\n\nB = textimag(Y)","title":"DC Model"}]
}
